package cb

import (
	"errors"
	"sync"
	"time"
)

// ErrOpen is returned when the circuit is open.
var ErrOpen = errors.New("circuit breaker is open")

// State represents the circuit state.
type State int

const (
	StateClosed   State = iota // normal operation
	StateOpen                  // rejecting all calls
	StateHalfOpen              // testing if service recovered
)

// CircuitBreaker protects a downstream service.
type CircuitBreaker struct {
	mu           sync.Mutex
	state        State
	failures     int
	maxFailures  int
	openUntil    time.Time
	resetTimeout time.Duration
}

// New creates a CircuitBreaker.
// maxFailures: failures before opening.
// resetTimeout: how long to stay open before trying half-open.
func New(maxFailures int, resetTimeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:        StateClosed,
		maxFailures:  maxFailures,
		resetTimeout: resetTimeout,
	}
}

// Call executes fn through the circuit breaker.
// Returns ErrOpen immediately if the circuit is open.
func (c *CircuitBreaker) Call(fn func() error) error {
	// TODO: implement circuit breaker state machine
	return fn()
}

// State returns current state (for testing).
func (c *CircuitBreaker) GetState() State {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.state
}

