package cb_test

import (
	"errors"
	"testing"
	"time"

	"github.com/ai-verification/circuit-breaker/cb"
)

var errService = errors.New("service error")

func TestClosedStateAllowsCalls(t *testing.T) {
	cb := cb.New(3, time.Second)
	err := cb.Call(func() error { return nil })
	if err != nil {
		t.Fatalf("expected nil, got %v", err)
	}
	if cb.GetState() != cb.StateClosed {
		t.Fatal("expected closed state")
	}
}

func TestOpensAfterMaxFailures(t *testing.T) {
	cb := cb.New(3, time.Second)
	for i := 0; i < 3; i++ {
		cb.Call(func() error { return errService })
	}
	if cb.GetState() != cb.StateOpen {
		t.Fatal("expected open state after 3 failures")
	}
}

func TestOpenStateRejectsWithErrOpen(t *testing.T) {
	cb := cb.New(1, time.Second)
	cb.Call(func() error { return errService })
	err := cb.Call(func() error { return nil })
	if !errors.Is(err, cb.ErrOpen) {
		t.Fatalf("expected ErrOpen, got %v", err)
	}
}

func TestHalfOpenAfterTimeout(t *testing.T) {
	cb := cb.New(1, 20*time.Millisecond)
	cb.Call(func() error { return errService })
	time.Sleep(30 * time.Millisecond)
	// Next call should be allowed (half-open probe)
	cb.Call(func() error { return nil })
	if cb.GetState() != cb.StateClosed {
		t.Fatal("expected closed after successful probe")
	}
}

func TestHalfOpenFailureReopens(t *testing.T) {
	cb := cb.New(1, 20*time.Millisecond)
	cb.Call(func() error { return errService })
	time.Sleep(30 * time.Millisecond)
	// Probe fails — should go back to open
	cb.Call(func() error { return errService })
	if cb.GetState() != cb.StateOpen {
		t.Fatal("expected open after failed half-open probe")
	}
}

func TestSuccessResetsFailureCount(t *testing.T) {
	cb := cb.New(3, time.Second)
	cb.Call(func() error { return errService })
	cb.Call(func() error { return errService })
	cb.Call(func() error { return nil }) // success should reset
	cb.Call(func() error { return errService })
	cb.Call(func() error { return errService })
	if cb.GetState() != cb.StateClosed {
		t.Fatal("should not open after reset")
	}
}
